import{_ as o,l,o as t,c as n,v as e,p as s,x as r,d as m,i as h,S as u}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"粗糙波动","description":"","frontmatter":{"title":"粗糙波动","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rough-vol.md","filePath":"quant/rough-vol.md","lastUpdated":1789023840000}'),p={name:"quant/rough-vol.md"};function B(d,a,g,E,H,c){const i=l("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="粗糙波动" tabindex="-1">粗糙波动 <a class="header-anchor" href="#粗糙波动" aria-label="Permalink to &quot;粗糙波动&quot;">​</a></h1><div class="epigraph"><p>已实现波动的对数增量在短间隔上呈现接近 $0.1$ 的 Hurst 指数：路径比布朗运动更「糙」，短端偏斜因此可以很陡，却不必引入独立的跳跃过程。</p><footer>—— Gatheral, Jaisson and Rosenbaum, Volatility is rough, Quantitative Finance, 2018；定价见 Bayer, Friz and Gatheral, Pricing under rough volatility, Quantitative Finance, 2016</footer></div><p><a href="/quant/heston">Heston</a> 的方差是半鞅，样本路径在短尺度上像 \\(\\sqrt{\\Delta t}\\) 的扩散；<a href="/quant/bergomi">Bergomi</a> 用指数核驱动远期方差曲线，核在 \\(T\\downarrow t\\) 处仍有界。高频已实现方差的时间序列却显示另一件事：对数波动的增量方差按 \\(\\Delta^{2H}\\) 缩放，且 \\(H\\) 显著小于 \\(1/2\\)。Jim Gatheral、Thibault Jaisson 与 Mathieu Rosenbaum 把这一经验规律写成「波动是粗糙的」。Christian Bayer、Peter Friz 与 Gatheral 随后给出粗糙 Bergomi（rBergomi）：把经典 Bergomi 的指数核换成分数核 \\((T-t)^{H-1/2}\\)，使瞬时方差的 Hölder 正则性掉到 \\(H\\)。本篇写这一经验事实、分数核如何进入定价，以及它与 <a href="/quant/dupire">Dupire</a> 局部波动、经典随机波动的分工；不把 Heston 五参数再推一遍，也不重复 Bergomi 两因子指数核的推导。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(\\sigma_t\\) 为瞬时或已实现波动的代理。对间隔 \\(\\Delta\\)，考察</p> \\[\\mathbb{E}\\bigl[(\\log\\sigma_{t+\\Delta}-\\log\\sigma_t)^2\\bigr] \\propto \\Delta^{2H}. \\]<p>布朗运动对应 \\(H=1/2\\)；Comte 与 Renault（1998）的长期记忆随机波动取 \\(H\\gt 1/2\\)，路径比布朗更光滑，能生成持久自相关，却把短端微笑抹平。市场短到期的偏斜极陡，香草翼与 <a href="/quant/variance-swap-vix">方差互换</a> 的短端都要求「刚刚发生的波动冲击仍在、且非常糙」。粗糙波动把 \\(H\\) 放到 \\((0,1/2)\\)：自相关在短尺度衰减得比扩散慢（实际是更强的短期依赖），路径几乎处处不可微、比半鞅更不规则。问题是：这样的对象还能否成为无套利定价的状态，以及欧式、VIX 产品如何计算。</p><p>半鞅假设一旦放弃，Itô 公式不再以经典形式成立，特征函数也失去仿射 Riccati。Bayer–Friz–Gatheral 的策略不是去找新的闭式，而是把 Bergomi 的远期方差曲线 \\(\\xi_t(T)=\\mathbb{E}[v_T\\mid\\mathcal{F}_t]\\) 保留为鞅，只改驱动核的正则性。今日的 <a href="/quant/bergomi">方差曲线</a> 仍可从市场上填入，动态由一条分数布朗运动给出。</p><h3 id="为何-能抬短端偏斜" tabindex="-1">为何 \\(H\\lt 1/2\\) 能抬短端偏斜 <a class="header-anchor" href="#为何-能抬短端偏斜" aria-label="Permalink to &quot;为何 $H\\lt 1/2$ 能抬短端偏斜&quot;">​</a></h3><p>偏斜的短端由「现货刚动时，方差来得及跟多快」决定。指数核 \\(e^{-k(T-t)}\\) 在 \\(T=t\\) 处有限，瞬时 vol-of-vol 被一个数钉死；要把短端偏斜做陡，必须把整个曲线的 vol-of-vol 抬高，长方差互换就会被搅过头。分数核 \\((T-t)^{H-1/2}\\) 在 \\(H\\lt 1/2\\) 时于 \\(T\\downarrow t\\) 发散：近端方差对刚刚发生的冲击极度敏感，远端核可积、冲击被稀释。于是同一 \\(\\eta\\)（vol-of-vol 水平）可以同时服务陡的两周偏斜与相对平静的一年方差。这正是一因子 rBergomi 相对两因子经典 Bergomi 的结构性优势，而不是多填了一个参数那么简单。</p><p><span class="marginnote">\\(H\\) 不是「再加一个随机因子」。它改的是同一条噪声的时间正则性。把 \\(H\\) 估成 \\(0.1\\) 再把模型当 Heston 用——路径生成、对冲比、短端 Vega 桶都会错。估 \\(H\\) 应来自已实现方差的尺度律，而不是用香草去「反解一个 Hurst」却不加正则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>经验侧。</strong> Gatheral–Jaisson–Rosenbaum 用牛津—曼氏已实现库等数据，对 \\(\\log\\sigma\\) 的 \\(q\\) 阶变差做 \\(\\Delta\\) 的回归，得到 \\(H\\) 在股权指数上稳定地落在 \\(0.1\\) 附近，且这一指数在 2008 年附近也不跳到 \\(1/2\\)。关键对照：若波动是 Heston 或经典 Bergomi 的扩散，短 \\(\\Delta\\) 的尺度应接近 \\(1/2\\)。数据拒绝这一条，却并不拒绝「远期方差是鞅」——粗糙的是路径，不是无套利的曲线约束。</p><p><strong>定价侧：rBergomi。</strong> 令</p> \\[\\xi_t(u)=\\xi_0(u)\\exp\\Biggl(\\eta\\sqrt{2H}\\int_0^t(u-s)^{H-1/2}\\,\\mathrm{d}W_s-\\frac{\\eta^2}{2}\\bigl[u^{2H}-(u-t)^{2H}\\bigr]\\Biggr), \\]<p>现货 \\(\\mathrm{d}S_t/S_t=\\sqrt{\\xi_t(t)}\\,\\mathrm{d}Z_t\\)，\\(\\mathrm{d}\\langle W,Z\\rangle=\\rho\\,\\mathrm{d}t\\)。\\(\\xi_0(u)\\) 仍从市场方差互换（或香草条带）输入，见 <a href="/quant/var-swap-replication">方差互换复制</a>。欧式没有仿射特征函数，定价用带 Volterra 核的高斯过程模拟：一次生成整条曲线上的积分，再取对角线得 \\(v_t\\)。Bayer–Friz–Gatheral 给出混合布朗与超收敛的数值方案；后续有基于 Wiener 混沌与核回归的加速。</p><p><strong>校准分层。</strong> 与经典 Bergomi 相同：\\(\\xi_0\\) 不参与香草最小二乘；\\(H\\) 优先用时间序列钉住或放在窄先验；\\(\\eta,\\rho\\) 拟合偏斜期限结构。把 \\(H\\) 完全交给香草去自由优化，往往会把它推向短端过拟合、与已实现尺度律冲突。粗糙 Heston（El Euch–Gatheral–Rosenbaum）用分数 Riccati 恢复特征函数路线，适合要做 <a href="/quant/carr-madan">Carr–Madan FFT</a> 的场合，但方差曲线形状不如 rBergomi 自由。</p><h3 id="与局部波动、跳跃的边界划分" tabindex="-1">与局部波动、跳跃的边界划分 <a class="header-anchor" href="#与局部波动、跳跃的边界划分" aria-label="Permalink to &quot;与局部波动、跳跃的边界划分&quot;">​</a></h3><p><a href="/quant/dupire">Dupire</a> 仍只锁定边际。粗糙波动提供的是动态：短端陡偏斜来自核的奇性，不必把 \\(\\sigma_{\\mathrm{loc}}(K,T)\\) 在 \\(T\\to 0\\) 做成尖峰。若坚持纯扩散的 Dupire 去贴极短到期，局部波动会在短 \\(T\\) 爆炸，看起来像跳；rBergomi 把同一现象解释成粗糙路径。这不是说市场没有跳——已实现测度里的大增量仍在——而是说「短端微笑」这一欧式事实，连续但非半鞅的方差已经能生成很大一块。跳跃与粗糙可以叠加，识别上必须用路径产品或已实现跳检验，不能单靠香草。</p>',19)),(t(),s(u,null,{default:r(()=>[h(i,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20RV%5B%22%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%E5%B0%BA%E5%BA%A6%E5%BE%8B%22%5D%20--%3E%20H%5B%22Hurst%20H%20%E7%BA%A6%200.1%22%5D%0A%20%20VS%5B%22%E5%B8%82%E5%9C%BA%E6%96%B9%E5%B7%AE%E6%9B%B2%E7%BA%BF%20%CE%BE_0%22%5D%20--%3E%20rB%5B%22rBergomi%20%E5%88%86%E6%95%B0%E6%A0%B8%22%5D%0A%20%20H%20--%3E%20rB%0A%20%20Rho%5B%22%E7%8E%B0%E8%B4%A7%E7%9B%B8%E5%85%B3%20%CF%81%22%5D%20--%3E%20rB%0A%20%20rB%20--%3E%20Skew%5B%22%E7%9F%AD%E7%AB%AF%E9%99%A1%E5%81%8F%E6%96%9C%22%5D%0A%20%20rB%20--%3E%20VIX%5B%22VIX%20%E6%9C%9F%E8%B4%A7%E5%87%B8%E6%80%A7%22%5D%0A%20%20rB%20--%3E%20Path%5B%22%E8%B7%AF%E5%BE%84%E4%BA%A7%E5%93%81%3A%20%E9%9D%9E%E5%8D%8A%E9%9E%85%E5%8A%A8%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分数布朗运动 \\(W^H\\) 的协方差使增量在短间隔上的均方正比于 \\(|\\Delta|^{2H}\\)。把这种噪声注入 \\(\\log\\xi\\)，瞬时方差 \\(v_t=\\xi_t(t)\\) 的样本路径几乎处处只 Hölder-\\(H\\)。对冲意义上，Gamma 误差不再是经典的 \\(\\tfrac12\\Gamma S^2(\\sigma^2-\\sigma_{\\mathrm{imp}}^2)\\Delta t\\) 加上普通的离散误差：方差本身的二次变差在短尺度上更凶，离散对冲要把步长收得比 Heston 更短，才能达到同一残差。这与「波动聚类」不是同一句话：聚类是方差的自相关在日、周尺度上为正；粗糙是<strong>无穷小尺度</strong>上的正则性。可以同时有粗糙短路径与缓慢的长因子。</p><p>无套利并不要求状态是半鞅，但要求可交易资产是半鞅（在适当条件下）。rBergomi 把可交易的方差互换曲线写成鞅 \\(\\xi_t(u)\\)，现货写成由 \\(v_t\\) 驱动的积分，价格过程仍是半鞅；非半鞅的是潜在的瞬时方差路径。因此「粗糙」攻击的是马尔可夫扩散这一建模习惯，不是风险中性定价本身。Fukasawa 等人把短端偏斜的爆破速度与 \\(H\\) 联系起来：偏斜对 \\(\\sqrt{T}\\) 的发散阶被 \\(H\\) 限制，这给「\\(H\\) 能否从香草识别」提供了理论锚，也解释了为何 Heston（有效 \\(H=1/2\\)）永远嫌短端不够陡。</p><h3 id="模拟-volterra-高斯与对角线" tabindex="-1">模拟：Volterra 高斯与对角线 <a class="header-anchor" href="#模拟-volterra-高斯与对角线" aria-label="Permalink to &quot;模拟：Volterra 高斯与对角线&quot;">​</a></h3><p>rBergomi 的指数里是对核 \\(K(u,s)=(u-s)^{H-1/2}\\) 的 Wiener 积分，属于高斯 Volterra 过程。一条路径上所有到期的 \\(\\log\\xi_t(u)\\) 联合正态，协方差由核的 \\(L^2\\) 内积给出。实现上先对一组基准 \\(u_j\\) 做一次协方差分解（Cholesky 或 Circulant 嵌入），再对 \\(t\\) 推进；对角线 \\(u=t\\) 要单独处理奇性。步长与基准到期的选择会改变短端偏斜的数值，应把模拟规格与校准规格绑在一起，避免「香草用细核、障碍用粗核」。</p><p><span class="marginnote">粗糙不是长期记忆的同义词。\\(H\\gt 1/2\\) 才是更光滑、更长记忆的 Comte–Renault 世界；\\(H\\lt 1/2\\) 是更糙、短端更陡。文献里「分数波动」两族不要混引。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>估计 \\(H\\) 依赖已实现方差的构造：噪声修正、隔夜、跳跃剔除都会移动点估计。把微观结构噪声当成「更糙」，会把 \\(H\\) 估低。定价若用历史 \\(H\\)、风险中性 \\(\\eta\\)，中间隔着波动率风险溢价；两个测度下的 \\(H\\) 不必相同，尽管经验上常常接近。欧式校准不能证明路径正则性——那是时间序列命题。</p><p>计算上 rBergomi 比 Heston 重，比带跳的仿射模型更重。生产上常见折中：短端用粗糙或跳，长端用经典两因子 Bergomi 或 <a href="/quant/local-stoch-vol">局部随机波动</a> 补香草残差。不要把 2016 年的定价论文写成 2018 年经验论文的推论：Bayer–Friz–Gatheral 是模型与数值；Gatheral–Jaisson–Rosenbaum 是尺度律。分数布朗在 \\(H\\neq 1/2\\) 时不是半鞅，也不能用普通 Itô 对 \\(W^H\\) 本身做交易。</p><p><span class="marginnote">出处不要写成「Gatheral 发明了分数布朗」。Mandelbrot–Van Ness 给出 \\(W^H\\)；Comte–Renault 把它接到随机波动但取光滑侧；粗糙波动的贡献是把 \\(H\\) 放到数据所在的一侧，并写出可校准的曲线模型。</span></p><p><span class="marginnote">用 rBergomi 给 <a href="/quant/vix-futures">VIX 期货</a> 定价时，标的是未来三十天方差的平方根，分数核对短端凸性极敏感。Heston 的均值回复会系统性低估这一凸性，这是粗糙核进入 VIX 账的主要理由之一。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>已实现对数波动的尺度律给出 \\(H\\approx 0.1\\)，路径比半鞅扩散更粗糙；短端偏斜可由此生成，而不必单靠跳跃。</li><li>rBergomi 保留 Bergomi 的远期方差鞅，把指数核换成 \\((T-t)^{H-1/2}\\)；今日 \\(\\xi_0\\) 仍来自市场方差曲线。</li><li>\\(H\\) 应用时间序列锚定；\\(\\eta,\\rho\\) 拟合偏斜。把 \\(H\\) 当普通香草参数自由漂，会与经验尺度冲突。</li><li>可交易价格仍是半鞅；非半鞅的是瞬时方差路径。Dupire 只管边际，不管这条路径。</li><li>粗糙（\\(H\\lt 1/2\\)）与长期记忆（\\(H\\gt 1/2\\)）是相反的正则性，不能混称「分数波动」。</li><li>出处：Gatheral, Jaisson and Rosenbaum, <em>Quantitative Finance</em>, 2018；Bayer, Friz and Gatheral, <em>Quantitative Finance</em>, 2016；对照 Comte and Renault, <em>Mathematical Finance</em>, 1998；曲线对象见 Bergomi。</li></ul>',13))])}const f=o(p,[["render",B]]);export{A as __pageData,f as default};
